//! Ported from src/conf.c (CodeCoreMorph, D-68): the library's settings. They apply to the
//! words counted from then on, in every table.

use std::sync::atomic::Ordering;

use crate::bridge::conf::{wf_conf_fold_case, wf_conf_min_length};

/// The shortest word counted, in bytes, until it is set.
pub const DEFAULT_MIN_LENGTH: usize = 1;

/// Words shorter than `min` bytes are skipped.
pub fn set_min_length(min: usize) {
    wf_conf_min_length.store(min, Ordering::Relaxed);
}

/// The shortest word counted, in bytes.
pub fn min_length() -> usize {
    wf_conf_min_length.load(Ordering::Relaxed)
}

/// Whether letters are folded to lower case.
pub fn set_fold_case(fold: bool) {
    wf_conf_fold_case.store(i32::from(fold), Ordering::Relaxed);
}

/// Whether letters are folded to lower case.
pub fn fold_case() -> bool {
    wf_conf_fold_case.load(Ordering::Relaxed) != 0
}

