//! Ported from src/htab.c (CodeCoreMorph, D-68): words and their counts in a hash table with
//! separate chaining.

/// A table grows past this many entries per bucket.
const LOAD: usize = 3;

/// FNV-1a, 32 bits wide.
pub fn hash(bytes: &[u8]) -> u32 {
    bytes.iter().fold(2_166_136_261_u32, |h, &b| (h ^ u32::from(b)).wrapping_mul(16_777_619))
}

/// A word and its count. The key is stored with a NUL after it, so its bytes can be handed
/// out as a C string; they stay where they are as long as the entry is in the table.
#[derive(Debug)]
pub struct Entry {
    key: Box<[u8]>,
    count: u64,
}

impl Entry {
    /// The word.
    pub fn key(&self) -> &[u8] {
        &self.key[..self.key.len() - 1]
    }

    /// The word and a NUL.
    pub fn key_with_nul(&self) -> &[u8] {
        &self.key
    }

    /// How many times it was counted.
    pub fn count(&self) -> u64 {
        self.count
    }
}

/// A count would go past `u64::MAX`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Overflow;

/// Words and their counts, in chains of buckets that double when they get long.
#[derive(Debug)]
pub struct Table {
    buckets: Vec<Vec<Entry>>,
    size: usize,
}

impl Table {
    /// An empty table of `nbuckets` buckets, or `None` for none.
    pub fn with_buckets(nbuckets: usize) -> Option<Self> {
        if nbuckets == 0 {
            return None;
        }
        Some(Self { buckets: (0..nbuckets).map(|_| Vec::new()).collect(), size: 0 })
    }

    /// How many different words it holds.
    pub fn len(&self) -> usize {
        self.size
    }

    pub fn is_empty(&self) -> bool {
        self.size == 0
    }

    /// How many buckets it has now.
    pub fn buckets(&self) -> usize {
        self.buckets.len()
    }

    fn slot(&self, key: &[u8]) -> usize {
        hash(key) as usize % self.buckets.len()
    }

    /// The entry of `key`, if it has been counted.
    pub fn find(&self, key: &[u8]) -> Option<&Entry> {
        self.buckets[self.slot(key)].iter().find(|e| e.key() == key)
    }

    /// The count of `key`: 0 when it isn't in the table.
    pub fn get(&self, key: &[u8]) -> u64 {
        self.find(key).map_or(0, Entry::count)
    }

    /// Adds `n` to the count of `key`, which a new word starts at. A count that would overflow
    /// is refused, and the old one stays.
    pub fn add(&mut self, key: &[u8], n: u64) -> Result<(), Overflow> {
        let slot = self.slot(key);
        if let Some(entry) = self.buckets[slot].iter_mut().find(|e| e.key() == key) {
            entry.count = entry.count.checked_add(n).ok_or(Overflow)?;
            return Ok(());
        }
        let mut stored = Vec::with_capacity(key.len() + 1);
        stored.extend_from_slice(key);
        stored.push(0);
        self.buckets[slot].push(Entry { key: stored.into_boxed_slice(), count: n });
        self.size += 1;
        if self.size > self.buckets.len() * LOAD {
            self.grow();
        }
        Ok(())
    }

    /// Twice the buckets, every entry moved to its new one (the keys' bytes don't move).
    fn grow(&mut self) {
        let n = self.buckets.len() * 2;
        let mut buckets: Vec<Vec<Entry>> = (0..n).map(|_| Vec::new()).collect();
        for entry in self.buckets.drain(..).flatten() {
            buckets[hash(entry.key()) as usize % n].push(entry);
        }
        self.buckets = buckets;
    }

    /// Every entry once, in no particular order.
    pub fn iter(&self) -> impl Iterator<Item = &Entry> {
        self.buckets.iter().flatten()
    }
}

//! The C functions of src/htab.c, exported under their names over `crate::htab`. A C `htab`
//! keeps the fields C reads (`nbuckets`, `size`) up to date; its `buckets` holds the Rust
//! table, which C never reads through.

use std::ffi::{c_char, c_ulong, c_void};
use std::{ptr, slice};

use super::{set_errno, sys, EINVAL};
use crate::htab::{self, Table};

/// `n` bytes at `s` (none when `n` is 0, whatever `s` is).
unsafe fn bytes<'a>(s: *const c_char, n: usize) -> &'a [u8] {
    if n == 0 {
        &[]
    } else {
        slice::from_raw_parts(s.cast::<u8>(), n)
    }
}

/// The table behind an initialized `htab`.
unsafe fn table<'a>(h: *const sys::htab) -> &'a Table {
    &*(*h).buckets.cast::<Table>()
}

/// The fields C reads, from the table.
unsafe fn update(h: *mut sys::htab) {
    let (nbuckets, size) = {
        let t = table(h);
        (t.buckets(), t.len())
    };
    (*h).nbuckets = nbuckets;
    (*h).size = size;
}

#[no_mangle]
pub unsafe extern "C" fn wf_hash(s: *const c_char, n: usize) -> c_ulong {
    c_ulong::from(htab::hash(bytes(s, n)))
}

#[no_mangle]
pub unsafe extern "C" fn htab_init(h: *mut sys::htab, nbuckets: usize) -> sys::wf_status {
    let Some(table) = Table::with_buckets(nbuckets) else {
        set_errno(EINVAL);
        return sys::wf_status_WF_EINVAL;
    };
    (*h).buckets = Box::into_raw(Box::new(table)).cast::<*mut sys::hentry>();
    update(h);
    sys::wf_status_WF_OK
}

#[no_mangle]
pub unsafe extern "C" fn htab_add(
    h: *mut sys::htab,
    key: *const c_char,
    len: usize,
    n: c_ulong,
) -> sys::wf_status {
    let added = (*(*h).buckets.cast::<Table>()).add(bytes(key, len), n as u64);
    update(h);
    match added {
        Ok(()) => sys::wf_status_WF_OK,
        Err(htab::Overflow) => sys::wf_status_WF_ERANGE,
    }
}

#[no_mangle]
pub unsafe extern "C" fn htab_get(h: *const sys::htab, key: *const c_char, len: usize) -> c_ulong {
    table(h).get(bytes(key, len)) as c_ulong
}

/// Calls `visit` with each word as a C `hentry`, whose `key` stays valid while the word is in
/// the table (callers keep it); `next` is NULL.
#[no_mangle]
pub unsafe extern "C" fn htab_each(h: *const sys::htab, visit: sys::htab_visit, ctx: *mut c_void) {
    let Some(visit) = visit else {
        return;
    };
    for entry in table(h).iter() {
        let e = sys::hentry {
            key: entry.key_with_nul().as_ptr().cast_mut().cast::<c_char>(),
            len: entry.key().len(),
            count: entry.count() as c_ulong,
            next: ptr::null_mut(),
        };
        visit(&e, ctx);
    }
}

#[no_mangle]
pub unsafe extern "C" fn htab_free(h: *mut sys::htab) {
    if !(*h).buckets.is_null() {
        drop(Box::from_raw((*h).buckets.cast::<Table>()));
    }
    (*h).buckets = ptr::null_mut();
    (*h).nbuckets = 0;
    (*h).size = 0;
}

