    unsafe { *__errno_location() = value };
}

//! Ported from src/sbuf.c (CodeCoreMorph, D-68): a growable byte buffer.

/// The smallest capacity a buffer grows to.
pub const MIN_CAPACITY: usize = 16;

/// A buffer can't hold that many bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TooLarge;

/// The capacity a buffer of `len` bytes in `cap` needs for `extra` more and a NUL after them:
/// `None` when it has room, else `cap` (or `MIN_CAPACITY`) doubled until it does.
pub fn capacity_for(len: usize, cap: usize, extra: usize) -> Result<Option<usize>, TooLarge> {
    let wanted = len.checked_add(extra).and_then(|n| n.checked_add(1)).ok_or(TooLarge)?;
    if wanted <= cap {
        return Ok(None);
    }
    let mut grown = if cap == 0 { MIN_CAPACITY } else { cap };
    while grown < wanted {
        grown = grown.checked_mul(2).ok_or(TooLarge)?;
    }
    Ok(Some(grown))
}

/// A growable byte buffer that grows as the C one did, by doubling from `MIN_CAPACITY`.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct Buffer {
    bytes: Vec<u8>,
}

impl Buffer {
    /// An empty buffer, with no memory yet.
    pub fn new() -> Self {
        Self::default()
    }

    /// Appends `s`.
    pub fn append(&mut self, s: &[u8]) -> Result<(), TooLarge> {
        if let Some(cap) = capacity_for(self.bytes.len(), self.bytes.capacity(), s.len())? {
            self.bytes.reserve_exact(cap - self.bytes.len());
        }
        self.bytes.extend_from_slice(s);
        Ok(())
    }

    /// Appends one byte.
    pub fn push(&mut self, c: u8) -> Result<(), TooLarge> {
        self.append(&[c])
    }

    /// Empties the buffer and keeps its memory.
    pub fn clear(&mut self) {
        self.bytes.clear();
    }

    /// Empties the buffer and gives its memory back.
    pub fn release(&mut self) {
        self.bytes = Vec::new();
    }

    /// The bytes.
    pub fn as_bytes(&self) -> &[u8] {
        &self.bytes
    }

    pub fn len(&self) -> usize {
        self.bytes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.bytes.is_empty()
    }

    /// How many bytes it holds before it grows again.
    pub fn capacity(&self) -> usize {
        self.bytes.capacity()
    }
}

//! The C functions of src/sbuf.c, exported under their names over `crate::sbuf`. A C `sbuf`
//! keeps its own memory, from C's allocator: C code reads `data` (NUL-terminated once it has
//! data), `len` and `cap`.

use std::ffi::{c_char, c_int, c_void};
use std::ptr;

use super::sys;
use crate::sbuf::{capacity_for, TooLarge};

extern "C" {
    fn realloc(ptr: *mut c_void, size: usize) -> *mut c_void;
    fn free(ptr: *mut c_void);
}

#[no_mangle]
pub unsafe extern "C" fn sbuf_init(b: *mut sys::sbuf) {
    (*b).data = ptr::null_mut();
    (*b).len = 0;
    (*b).cap = 0;
}

/// Room for `extra` more bytes and a NUL.
unsafe fn grow(b: &mut sys::sbuf, extra: usize) -> sys::wf_status {
    match capacity_for(b.len, b.cap, extra) {
        Err(TooLarge) => sys::wf_status_WF_ERANGE,
        Ok(None) => sys::wf_status_WF_OK,
        Ok(Some(cap)) => {
            let data = realloc(b.data.cast::<c_void>(), cap);
            if data.is_null() {
                return sys::wf_status_WF_ENOMEM;
            }
            b.data = data.cast::<c_char>();
            b.cap = cap;
            sys::wf_status_WF_OK
        }
    }
}

#[no_mangle]
pub unsafe extern "C" fn sbuf_append(
    b: *mut sys::sbuf,
    s: *const c_char,
    n: usize,
) -> sys::wf_status {
    let b = &mut *b;
    let status = grow(b, n);
    if status != sys::wf_status_WF_OK {
        return status;
    }
    if n > 0 {
        ptr::copy(s, b.data.add(b.len), n);
    }
    b.len += n;
    *b.data.add(b.len) = 0;
    sys::wf_status_WF_OK
}

#[no_mangle]
pub unsafe extern "C" fn sbuf_putc(b: *mut sys::sbuf, c: c_int) -> sys::wf_status {
    let ch = c as c_char;
    sbuf_append(b, &ch, 1)
}

#[no_mangle]
pub unsafe extern "C" fn sbuf_reset(b: *mut sys::sbuf) {
    (*b).len = 0;
    if !(*b).data.is_null() {
        *(*b).data = 0;
    }
}

#[no_mangle]
pub unsafe extern "C" fn sbuf_free(b: *mut sys::sbuf) {
    free((*b).data.cast::<c_void>());
    sbuf_init(b);
}

//! Ported from src/tok.c (CodeCoreMorph, D-68): splits text into words, runs of letters and
//! digits with an apostrophe allowed between two letters ("don't"). Words shorter than the
//! minimum length are skipped; letters are folded to lower case when the settings say so.

use crate::conf;
use crate::sbuf::{Buffer, TooLarge};

/// A letter or a digit (ASCII: C's `isalnum` in the C locale).
fn is_word_char(c: u8) -> bool {
    c.is_ascii_alphanumeric()
}

/// The words of a text, one at a time.
#[derive(Debug, Clone)]
pub struct Tokenizer<'a> {
    text: &'a [u8],
    pos: usize,
}

impl<'a> Tokenizer<'a> {
    pub fn new(text: &'a [u8]) -> Self {
        Self { text, pos: 0 }
    }

    /// How many bytes of the text it has read.
    pub fn position(&self) -> usize {
        self.pos
    }

    /// The next word into `word`: `Ok(true)`, or `Ok(false)` at the end of the text. A word
    /// too short to count is skipped (and stays in `word` when the text ends after it).
    pub fn next_word(&mut self, word: &mut Buffer) -> Result<bool, TooLarge> {
        let fold = conf::fold_case();
        let min = conf::min_length();
        loop {
            while self.pos < self.text.len() && !is_word_char(self.text[self.pos]) {
                self.pos += 1;
            }
            if self.pos == self.text.len() {
                return Ok(false);
            }
            word.clear();
            while self.pos < self.text.len() {
                let c = self.text[self.pos];
                let inside = c == b'\''
                    && !word.is_empty()
                    && self.text.get(self.pos + 1).is_some_and(u8::is_ascii_alphabetic)
                    && word.as_bytes().last().is_some_and(u8::is_ascii_alphabetic);
                if !inside && !is_word_char(c) {
                    break;
                }
                word.push(if fold { c.to_ascii_lowercase() } else { c })?;
                self.pos += 1;
            }
            if word.len() >= min {
                return Ok(true);
            }
        }
    }
}

//! The C functions of src/tok.c, exported under their names over `crate::tok`. A C
//! `tokenizer` points into the caller's text; the word goes into the caller's C `sbuf`.

use std::ffi::{c_char, c_int};
use std::slice;

use super::sbuf::{sbuf_append, sbuf_reset};
use super::sys;
use crate::sbuf::{Buffer, TooLarge};
use crate::tok::Tokenizer;

#[no_mangle]
pub unsafe extern "C" fn tok_init(t: *mut sys::tokenizer, text: *const c_char, len: usize) {
    (*t).p = text;
    (*t).end = text.wrapping_add(len);
}

#[no_mangle]
pub unsafe extern "C" fn tok_next(
    t: *mut sys::tokenizer,
    word: *mut sys::sbuf,
    found: *mut c_int,
) -> sys::wf_status {
    let t = &mut *t;
    let len = t.end as usize - t.p as usize;
    let text: &[u8] = if len == 0 { &[] } else { slice::from_raw_parts(t.p.cast::<u8>(), len) };
    let mut tokens = Tokenizer::new(text);
    let mut buffer = Buffer::new();
    let result = tokens.next_word(&mut buffer);
    t.p = t.p.wrapping_add(tokens.position());
    let more = match result {
        Err(TooLarge) => return sys::wf_status_WF_ERANGE,
        Ok(more) => more,
    };
    // The C wrote each word it read into `word`, the skipped ones too.
    if !buffer.is_empty() {
        sbuf_reset(word);
        let status = sbuf_append(word, buffer.as_bytes().as_ptr().cast::<c_char>(), buffer.len());
        if status != sys::wf_status_WF_OK {
            return status;
        }
    }
    *found = c_int::from(more);
    sys::wf_status_WF_OK
}

//! Ported from src/wf.c (CodeCoreMorph, D-68): the library's interface, tables of counted
//! words.

use std::fmt;

use crate::htab::{self, Table as Counts};
use crate::sbuf::Buffer;
use crate::tok::Tokenizer;

/// How many buckets a table starts with.
const BUCKETS: usize = 64;

/// What went wrong, as the C interface's status codes say it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    /// Out of memory (the C interface's `WF_ENOMEM`).
    NoMemory,
    /// A bad argument (`WF_EINVAL`).
    InvalidArgument,
    /// A count would overflow (`WF_ERANGE`).
    Range,
}

impl Error {
    /// The message the C interface gives for it.
    pub fn message(self) -> &'static str {
        match self {
            Error::NoMemory => "out of memory",
            Error::InvalidArgument => "invalid argument",
            Error::Range => "count out of range",
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.message())
    }
}

impl std::error::Error for Error {}

/// One counted word of a table.
#[derive(Debug, Clone, Copy)]
pub struct Word<'a> {
    entry: &'a htab::Entry,
}

impl<'a> Word<'a> {
    /// The word.
    pub fn text(&self) -> &'a [u8] {
        self.entry.key()
    }

    /// The word and a NUL, as the table keeps it.
    pub fn text_with_nul(&self) -> &'a [u8] {
        self.entry.key_with_nul()
    }

    /// How many times it was counted.
    pub fn count(&self) -> u64 {
        self.entry.count()
    }
}

/// A table of counted words.
#[derive(Debug)]
pub struct Table {
    words: Counts,
}

impl Default for Table {
    fn default() -> Self {
        Self::new()
    }
}

impl Table {
    /// An empty table.
    pub fn new() -> Self {
        Self { words: Counts::with_buckets(BUCKETS).expect("a table has buckets") }
    }

    /// Counts every word of `text` with the settings of `crate::conf`. On an error, the words
    /// before it stay counted.
    pub fn count_text(&mut self, text: &[u8]) -> Result<(), Error> {
        let mut tokens = Tokenizer::new(text);
        let mut word = Buffer::new();
        while tokens.next_word(&mut word).map_err(|_| Error::Range)? {
            self.words.add(word.as_bytes(), 1).map_err(|_| Error::Range)?;
        }
        Ok(())
    }

    /// How many different words it holds.
    pub fn len(&self) -> usize {
        self.words.len()
    }

    pub fn is_empty(&self) -> bool {
        self.words.is_empty()
    }

    /// How many times `word` was counted.
    pub fn lookup(&self, word: &[u8]) -> u64 {
        self.words.get(word)
    }

    /// The `n` most frequent words (fewer when the table holds fewer), most frequent first,
    /// ties in byte order.
    pub fn top(&self, n: usize) -> Vec<Word<'_>> {
        let mut words: Vec<Word<'_>> = self.words.iter().map(|entry| Word { entry }).collect();
        words.sort_by(|a, b| b.count().cmp(&a.count()).then_with(|| a.text().cmp(b.text())));
        words.truncate(n);
        words
    }
}

//! The C functions of src/wf.c, exported under their names over `crate::wf`. A `wf_table *`
//! is the Rust table, boxed.

use std::ffi::{c_char, c_ulong, CStr};
use std::slice;

use super::{set_errno, sys, EINVAL};
use crate::wf::{Error, Table};

fn status(error: Error) -> sys::wf_status {
    match error {
        Error::NoMemory => sys::wf_status_WF_ENOMEM,
        Error::InvalidArgument => sys::wf_status_WF_EINVAL,
        Error::Range => sys::wf_status_WF_ERANGE,
    }
}

/// The table behind a `wf_table *`, or `None` for NULL.
unsafe fn table<'a>(table: *const sys::wf_table) -> Option<&'a Table> {
    table.cast::<Table>().as_ref()
}

#[no_mangle]
pub unsafe extern "C" fn wf_table_new(out: *mut *mut sys::wf_table) -> sys::wf_status {
    if out.is_null() {
        set_errno(EINVAL);
        return sys::wf_status_WF_EINVAL;
    }
    *out = Box::into_raw(Box::new(Table::new())).cast::<sys::wf_table>();
    sys::wf_status_WF_OK
}

#[no_mangle]
pub unsafe extern "C" fn wf_table_free(table: *mut sys::wf_table) {
    if !table.is_null() {
        drop(Box::from_raw(table.cast::<Table>()));
    }
}

#[no_mangle]
pub unsafe extern "C" fn wf_count_text(
    table: *mut sys::wf_table,
    text: *const c_char,
    len: usize,
) -> sys::wf_status {
    let table = table.cast::<Table>().as_mut();
    let Some(table) = table.filter(|_| !(text.is_null() && len > 0)) else {
        set_errno(EINVAL);
        return sys::wf_status_WF_EINVAL;
    };
    let text: &[u8] = if len == 0 { &[] } else { slice::from_raw_parts(text.cast::<u8>(), len) };
    match table.count_text(text) {
        Ok(()) => sys::wf_status_WF_OK,
        Err(error) => status(error),
    }
}

#[no_mangle]
pub unsafe extern "C" fn wf_table_size(table: *const sys::wf_table) -> usize {
    self::table(table).map_or(0, Table::len)
}

#[no_mangle]
pub unsafe extern "C" fn wf_lookup(table: *const sys::wf_table, word: *const c_char) -> c_ulong {
    match self::table(table) {
        Some(table) if !word.is_null() => table.lookup(CStr::from_ptr(word).to_bytes()) as c_ulong,
        _ => 0,
    }
}

/// Writes the top words to `out`; each `text` is the table's, NUL-terminated.
#[no_mangle]
pub unsafe extern "C" fn wf_top(
    table: *const sys::wf_table,
    out: *mut sys::wf_word,
    n: usize,
) -> usize {
    let Some(table) = self::table(table).filter(|_| !(out.is_null() && n > 0)) else {
        set_errno(EINVAL);
        return 0;
    };
    if table.is_empty() || n == 0 {
        return 0;
    }
    let top = table.top(n);
    for (slot, word) in slice::from_raw_parts_mut(out, top.len()).iter_mut().zip(&top) {
        *slot = sys::wf_word {
            text: word.text_with_nul().as_ptr().cast::<c_char>(),
            len: word.text().len(),
            count: word.count() as c_ulong,
        };
    }
    top.len()
}

#[no_mangle]
pub extern "C" fn wf_strerror(status: sys::wf_status) -> *const c_char {
    let message: &'static CStr = match status {
        sys::wf_status_WF_OK => c"no error",
        sys::wf_status_WF_ENOMEM => c"out of memory",
        sys::wf_status_WF_EINVAL => c"invalid argument",
        sys::wf_status_WF_ERANGE => c"count out of range",
        _ => c"unknown error",
    };
    message.as_ptr()
}

