//! The program's runs that `make test` compares with files (tests/sample.out and
//! tests/sample-k.out), against the built program.
#![forbid(unsafe_code)]

use std::io::Write;
use std::process::{Command, Stdio};

fn data(name: &str) -> Vec<u8> {
    let path = format!("{}/../../tests/{name}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read(&path).unwrap_or_else(|e| panic!("{path}: {e}"))
}

/// The program's output and exit status, for `input` on its standard input.
fn run(args: &[&str], input: &[u8]) -> (Vec<u8>, Option<i32>) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_wordfreq"))
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("the program starts");
    child.stdin.take().expect("its input").write_all(input).expect("it reads its input");
    let output = child.wait_with_output().expect("it ends");
    (output.stdout, output.status.code())
}

#[test]
fn the_three_most_frequent_words() {
    let (out, code) = run(&["3"], &data("sample.txt"));
    assert_eq!(code, Some(0));
    assert_eq!(out, data("sample.out"));
}

#[test]
fn case_kept_and_short_words_skipped() {
    let (out, code) = run(&["-k", "-m", "4", "2"], &data("sample.txt"));
    assert_eq!(code, Some(0));
    assert_eq!(out, data("sample-k.out"));
}

#[test]
fn an_unknown_option_shows_the_usage() {
    let (out, code) = run(&["-x"], b"");
    assert_eq!(code, Some(2));
    assert!(out.is_empty());
}

