/// The words of `text`, joined by "|".
fn words(text: &str) -> String {
    let mut tokens = Tokenizer::new(text.as_bytes());
    let mut word = Buffer::new();
    let mut found = Vec::new();
    while tokens.next_word(&mut word).expect("the words fit") {
        found.push(String::from_utf8_lossy(word.as_bytes()).into_owned());
    }
    found.join("|")
}

#[test]
